package crush_test

import (
	"bufio"
	"os"
	"strconv"
	"strings"
	"testing"

	"github.com/unistack-org/crushkv/crush"
	"github.com/unistack-org/crushkv/crushmap"
)

// TestGoldenMapTxt compares placements produced by the Go engine against
// golden vectors generated by the verbatim Ceph CRUSH C core (crush/builder.c,
// crush/mapper.c, crush/hash.c) building the same map as testdata/map.txt
// (see files/ceph-crush/golden_harness.c in the session notes).
//
// Vector format: <prefix><ruleno> <x> <n> [osd...]
//
//	R = all osd weights 0x10000
//	W = osd.0 weight 0 (out of service)
func TestGoldenMapTxt(t *testing.T) {
	data, err := os.ReadFile("../crushmap/testdata/map.txt")
	if err != nil {
		t.Fatal(err)
	}
	m := crushmap.NewMap()
	if err := m.DecodeText(data); err != nil {
		t.Fatal(err)
	}
	cm, err := m.Compile()
	if err != nil {
		t.Fatal(err)
	}

	full := make([]uint32, 6)
	for i := range full {
		full[i] = 0x10000
	}
	out0 := make([]uint32, 6)
	copy(out0, full)
	out0[0] = 0

	work := crush.NewWork(cm, 10, nil)
	res := make([]int32, 3)

	f, err := os.Open("testdata/golden_maptxt.txt")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		prefix := fieldPrefix(fields[0])
		ruleno, _ := strconv.Atoi(fields[0][len(prefix):])
		x, _ := strconv.Atoi(fields[1])
		n, _ := strconv.Atoi(fields[2])
		want := fields[3:]

		weights := full
		if prefix == "W" {
			weights = out0
		}
		got := cm.DoRule(work, int32(ruleno), int32(x), res, weights)
		if got != n {
			t.Fatalf("%s rule %d x %d: n=%d, want %d (%s)", prefix, ruleno, x, got, n, line)
		}
		for i := 0; i < n; i++ {
			w, _ := strconv.Atoi(want[i])
			if int(res[i]) != w {
				t.Fatalf("%s rule %d x %d: result=%v, want %v", prefix, ruleno, x, res[:n], want)
			}
		}
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
}

func fieldPrefix(s string) string {
	i := 0
	for i < len(s) && !(s[i] >= '0' && s[i] <= '9') {
		i++
	}
	return s[:i]
}

// TestGoldenMap2 covers uniform/list/tree/straw2 buckets, choose to non-leaf
// types, fixed numrep, toosmall (result_max > devices), and progressive-out
// straw2 stability. Vectors from golden2_harness.c (verbatim Ceph core),
// map in crushmap/testdata/map2.txt.
//
//	B = all weights 1.0; T2 = rule 2 with result_max 8;
//	O = osd.3 out; A0 = rule 0 with osd.4 and osd.5 out.
func TestGoldenMap2(t *testing.T) {
	data, err := os.ReadFile("../crushmap/testdata/map2.txt")
	if err != nil {
		t.Fatal(err)
	}
	m := crushmap.NewMap()
	if err := m.DecodeText(data); err != nil {
		t.Fatal(err)
	}
	cm, err := m.Compile()
	if err != nil {
		t.Fatal(err)
	}
	full := make([]uint32, 10)
	for i := range full {
		full[i] = 0x10000
	}
	out3 := append([]uint32(nil), full...)
	out3[3] = 0
	out45 := append([]uint32(nil), full...)
	out45[4] = 0
	out45[5] = 0

	weightsFor := map[byte][]uint32{'B': full, 'T': full, 'O': out3, 'A': out45}
	maxFor := map[byte]int{'B': 3, 'T': 8, 'O': 3, 'A': 3}

	work := crush.NewWork(cm, 10, nil)
	res := make([]int32, 8)

	f, err := os.Open("testdata/golden_map2txt.txt")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()

	sc := bufio.NewScanner(f)
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		prefix := fieldPrefix(fields[0])
		ruleno, _ := strconv.Atoi(fields[0][len(prefix):])
		x, _ := strconv.Atoi(fields[1])
		n, _ := strconv.Atoi(fields[2])
		want := fields[3:]

		weights := weightsFor[prefix[0]]
		rmax := maxFor[prefix[0]]
		if prefix == "T2" {
			ruleno = 2
			rmax = 8
		}
		got := cm.DoRule(work, int32(ruleno), int32(x), res[:rmax], weights)
		if got != n {
			t.Fatalf("%s rule %d x %d: n=%d, want %d (%s)", prefix, ruleno, x, got, n, line)
		}
		for i := 0; i < n; i++ {
			w, _ := strconv.Atoi(want[i])
			if int(res[i]) != w {
				t.Fatalf("%s rule %d x %d: result=%v, want %v", prefix, ruleno, x, res[:n], want)
			}
		}
	}
	if err := sc.Err(); err != nil {
		t.Fatal(err)
	}
}

// TestGoldenMap3 covers the legacy tunables set (straw_calc_version 0,
// chooseleaf_descend_once 0, chooseleaf_vary_r 0, chooseleaf_stable 0,
// local 2 / local fallback 5 / total 19) with varied fractional weights,
// set_choose_tries and set_choose_local_tries rule overrides, N-1 numrep,
// and fractional-weight probabilistic out. Vectors from golden3_harness.c
// (verbatim Ceph core), map in crushmap/testdata/map3.txt.
//
//	B = all weights 1.0; F = osd.1 weight 0.5 (probabilistically out).
